const ELEMENT_PROP_KEYS = new Set(["theme","accent","accentLine","fontWeight","lockAt","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  accentLine: 2,
  fontWeight: 500,
  lockAt: 94,
  fontFamily: "Bricolage Grotesque",
  scale: 1,
  delay: 0,
  speed: 1,
};

type ParallaxLockupElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ParallaxLockupBase>;

const ParallaxLockupInner = forwardRef<
  HTMLDivElement,
  ParallaxLockupElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ParallaxLockup>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ParallaxLockupBase
          {...(componentProps as unknown as ComponentProps<typeof ParallaxLockupBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ParallaxLockup = Interactive.withSchema({
